        [Test, Requirement("FR-COOK-008"), Tc("GEN-FR-COOK-008-01")]
        public void TryPlace_CookableRawIngredient_PlacesOnStove()
        {
            var def = GenHelpers.Scriptable<IngredientDefinition>();
