            var placed = stove.TryPlace(item);
            Assert.That(stove.HasItem, Is.True, "근거: 사전조건: 조리 가능 + Raw 상태 입력: E 처리:  기대 결과: 화로에 놓임");
            Assert.That(stove.Current, Is.EqualTo(item), "근거: 사전조건: 조리 가능 + Raw 상태 입력: E 처리:  기대 결과: 화로에 놓임");
        }

        // 화로에 재료 적재 후 조리 시간(6초) 미만 경과 시 조리 진행 중 상태 확인
