        // Cooked 상태 패티를 화로에 7초간 방치 시 Burned 상태로 전이 확인
        [Test, Requirement("FR-COOK-010"), Tc("GEN-FR-COOK-010-01")]
        public void Patty_OverCookOnStove_TransitionsToBurned()
        {
            var def = GenHelpers.Scriptable<IngredientDefinition>();
