        // 손질 완료 후 Space 키 유지 시 칼질 동작 정지 및 설비 알림 확인
        [Test, Requirement("FR-COOK-018"), Tc("GEN-FR-COOK-018-01")]
        public void CuttingStation_WorkHeldAfterCompletion_NoWorkPending()
        {
            var def = GenHelpers.Scriptable<IngredientDefinition>();
            GenHelpers.SetMember(def, "Choppable", true);
            GenHelpers.SetMember(def, "ChopSeconds", 1);
            var item = GenHelpers.Component<IngredientItem>("item");
            item.Initialize(def, ProcessState.Raw);
            var station = GenHelpers.Component<CuttingStation>("station");
            station.TryPlace(item);
            station.OnWorkHeld(1);
            station.OnWorkHeld(0.5f);
            Assert.That(station.HasWorkPending, Is.False, "근거: 칼질 동작이 멈춤. 설비가 \"할 일 없음\"을 알림");
        }

        // 빈 도마에서 Space 입력 시 작업 동작 미시작 확인
        [Test, Requirement("FR-COOK-019"), Tc("GEN-FR-COOK-019-01")]
        public void EmptyCuttingStation_OnWorkHeld_DoesNotStartWork()
        {
            var station = GenHelpers.Component<CuttingStation>("station");
            station.OnWorkHeld(0.5f);
            Assert.That(station.HasWorkPending, Is.False, "근거: 작업 동작이 시작되지 않음");
            Assert.That(station.Progress01, Is.EqualTo(0), "근거: 작업 동작이 시작되지 않음");
        }

        // 내용물이 있는 접시를 들고 쓰레기통에 상호작용 시 내용물만 소멸하고 접시는 손에 유지되는지 검증
        [Test, Requirement("FR-COOK-014"), Tc("GEN-FR-COOK-014-01")]
        public void TrashStation_TryPlace_WithNonEmptyPlate_ClearsContentsAndKeepsPlateInHand()
        {
            var trashStation = GenHelpers.Component<TrashStation>("trashStation");
            var plate = GenHelpers.Component<PlateItem>("plate");
            var def = GenHelpers.Scriptable<IngredientDefinition>();
            var ingredient = GenHelpers.Component<IngredientItem>("ingredient");
            ingredient.Initialize(def, ProcessState.Raw);
            plate.TryAdd(ingredient);
            LogAssert.Expect(LogType.Error, new Regex("Destroy may not be called from edit mode!"));
            var placedResult = trashStation.TryPlace(plate);
            Assert.That(placedResult, Is.False, "근거: 내용물만 소멸, 접시는 손에 남음");
            Assert.That(plate.IsEmpty, Is.True, "근거: 내용물만 소멸, 접시는 손에 남음");
        }

        // 접시에 담긴 재료의 소유자가 접시로 변경되고 바닥 물건으로 인식되지 않는지 검증
